function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // conveyor belt
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2);
  ctx.lineTo(W, H/2);
  ctx.stroke();

  // ingredients
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(50 + 100 * Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(150 + 100 * Math.sin(t + Math.PI/2), H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(250 + 100 * Math.sin(t + Math.PI), H/2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // factory machines
  ctx.lineWidth = 5;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(300, H/2 - 50, 50, 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(400, H/2 - 50, 50, 100);
  ctx.stroke();

  // worker stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(200 + 20 * Math.sin(t), H/2 - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 80);
  ctx.lineTo(200 + 20 * Math.sin(t), H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 60);
  ctx.lineTo(180 + 20 * Math.sin(t), H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 60);
  ctx.lineTo(220 + 20 * Math.sin(t), H/2 - 40);
  ctx.stroke();

  ctx.restore();
}
